def decode_genome_from_nn_probs(
    *,
    probs_dir: Path,
    fasta: Path,
    stats: dict,
    length_model: LengthModel,
    overlap_probs: dict,
    min_nt: int,
    start_emission_scale: float,
    alpha: float,
    segmental_workers: int = 2,
    start_type_bonus_scale: float = 1.0,
    overlap_emission_scale: float = 1.0,
    conflict_resolution: str = "length",
    gene_length_lambda: float = 0.0,
    gene_length_center: bool = False,
    gene_entry_bonus: float = 0.0,
    boundary_emit_floor: float | None = None,
    max_overlap_depth: int = 50,
    rbs_bonus_by_seq: Dict[str, tuple] | None = None,
    start_rank_by_seq: Dict[str, tuple] | None = None,
    start_rank_lambda: float = 0.0,
    start_rank_center: bool = True,
    start_rank_existence_lambda: float | None = None,
) -> List[Dict]:
    """Run segmental decode on every sequence in *fasta* using cached nn_probs."""
    gs = GenomeSequences(fasta_file=str(fasta), min_seq_len=0)
    gs.encode_sequences()
    segmental_overlaps = segmental_overlap_range(max_overlap_depth)
    start_bonus = default_start_type_bonus(stats)
    if start_type_bonus_scale != 1.0:
        # The START-state emission already carries log P(start codon) via
        # hmm_prokaryotic.log_c_table(), so the default bonus applies the same
        # frequency prior a second time (GTG: -2.03 nats twice = -4.06 vs ATG).
        # Scale 0 removes the duplicate; 1.0 is the historical behaviour.
        start_bonus = {k: v * start_type_bonus_scale for k, v in start_bonus.items()}
    genes: List[Dict] = []
    for idx, seq_name in enumerate(gs.sequence_names):
        seq = gs.sequences[idx]
        L = len(seq)
        probs = _load_nn_probs_from_cache(probs_dir, seq_name, L)
        genes.extend(
            annotate_strategy_a_segmental(
                probs,
                seq,
                seq_name,
                stats,
                length_model,
                alpha=alpha,
                use_codon_c=True,
                same_strand_max_ov=max_overlap_depth,
                opposite_max_ov=max_overlap_depth,
                start_emission_scale=start_emission_scale,
                min_nt=min_nt,
                allowed_overlaps=segmental_overlaps,
                start_type_bonus=start_bonus,
                overlap_probs=overlap_probs,
                duration_lambda=0.0,
                gene_length_lambda=gene_length_lambda,
                gene_length_center=gene_length_center,
                gene_entry_bonus=gene_entry_bonus,
                boundary_emit_floor=boundary_emit_floor,
                overlap_emission_scale=overlap_emission_scale,
                conflict_resolution=conflict_resolution,
                rbs_bonus_plus=(rbs_bonus_by_seq or {}).get(seq_name, (None, None))[0],
                rbs_bonus_minus=(rbs_bonus_by_seq or {}).get(seq_name, (None, None))[1],
                start_rank_q_plus=(start_rank_by_seq or {}).get(seq_name, (None, None))[0],
                start_rank_q_minus=(start_rank_by_seq or {}).get(seq_name, (None, None))[1],
                start_rank_lambda=start_rank_lambda,
                start_rank_center=start_rank_center,
                start_rank_existence_lambda=start_rank_existence_lambda,
                segmental_overlap_score="empirical_multihot",
                empirical_connector_prior_lambda=1.0,
                segmental_workers=segmental_workers,
            ),
        )
    return genes


def build_start_rank_q(work: str, ckpt_path: Path, device: str = "cpu",
                       batch: int = 4096) -> "np.ndarray":
    """Raw neural ranker score at every start-codon position of ``work``.

    Unscaled and uncentred: the decoder centres per candidate set (all
    competitors for one stop) and applies lambda there, because a score that is
    only meaningful *relative to its own competitors* must not be allowed to act
    as a per-locus existence bonus.
    """
    import numpy as np
    import torch
    from .start_ranker import (UP_NT, DOWN_NT, WIN, FEATFN, build_model,
                                    encode_window)
    from .viterbi_decode import VALID_START_SET

    ck = torch.load(ckpt_path, map_location=device, weights_only=False)
    model = build_model(ck["model"], ck.get("width", 24), ck.get("kernel", 7))
    model.load_state_dict(ck["state"])
    model.to(device).eval()

    # The window needs UP_NT before and DOWN_NT after, so starts closer than
    # DOWN_NT to the end have no encodable window and keep a zero score.
    pos = [i for i in range(UP_NT, len(work) - DOWN_NT + 1)
           if work[i:i + 3] in VALID_START_SET]
    out = np.zeros(len(work), dtype=np.float64)
    if not pos:
        return out
    # encode_window needs (lo, hi); the window only depends on lo for '+', and
    # hi is unused there, so pass a dummy end past the start.
    wins = np.stack([encode_window(work, i, i + 3, "+") for i in pos])
    lens = np.full(len(pos), 300, dtype=np.int32)   # unused by the cnn model
    featfn = FEATFN.get(ck["model"])
    x = wins.astype(np.int64) if featfn is None else featfn(wins, lens)
    scores = np.empty(len(pos), dtype=np.float64)
    with torch.no_grad():
        for s0 in range(0, len(pos), batch):
            xt = torch.as_tensor(x[s0:s0 + batch], device=device)
            scores[s0:s0 + batch] = model(xt).float().cpu().numpy()
    out[np.array(pos)] = scores
    return out


def shuffle_start_bonus(work: str, arr: "np.ndarray", seed: int) -> "np.ndarray":
    """Permute a start bonus among the start positions it was assigned to.

    The null hypothesis for any start prior: does the *association* between
    upstream sequence and score carry the gain, or merely the perturbation? This
    preserves exactly which positions receive a bonus and the exact multiset of
    magnitudes, and destroys only the sequence-to-score mapping. A gain that
    survives this is not evidence about RBS motifs.
    """
    import numpy as np
    from .viterbi_decode import VALID_START_SET
    pos = np.array([i for i in range(len(work) - 2)
                    if work[i:i + 3] in VALID_START_SET], dtype=np.int64)
    out = np.zeros_like(arr)
    if pos.size:
        out[pos] = np.random.default_rng(seed).permutation(arr[pos])
    return out


def build_rbs_bonus(work: str, score_by_bin: Dict[int, float]) -> "np.ndarray":
    """Per-position start bonus on ``work`` (already strand-oriented).

    Only start-codon positions can begin an ORF, so only those are scored --
    ~216k positions per strand instead of 4.6M, which keeps this to seconds.
    """
    import numpy as np
    from .prodigal_rbs_bins import prodigal_rbs_bin_from_upstream
    from .viterbi_decode import VALID_START_SET
    out = np.zeros(len(work), dtype=np.float64)
    for i in range(45, len(work) - 2):
        if work[i:i + 3] in VALID_START_SET:
            out[i] = score_by_bin.get(prodigal_rbs_bin_from_upstream(work[i - 45:i]), 0.0)
    return out


def learn_rbs_bins(seqs: Dict[str, str], genes: List[Dict]) -> Dict[int, float]:
    """Self-train Prodigal-style RBS bin log-odds from our own first-pass calls.

    Counts are pooled over ALL contigs of the assembly, not per contig: a plasmid
    with a handful of genes cannot support a motif estimate on its own, and
    per-contig fitting measurably hurt the multi-contig test genomes
    (Synechococcus, 7 contigs, -0.0052 F1). The RBS motif is a property of the
    organism's translation machinery, so one model per assembly is also the
    biologically correct unit -- and it is what Prodigal does.

    Contrast is predicted starts vs the alternative in-frame starts of the same
    ORFs -- the competitors the decoder actually chooses between. No reference.
    """
    import math
    from collections import Counter
    from .rbs_start_prior import alt_starts, rbs_bin
    pos, neg = Counter(), Counter()
    for g in genes:
        sq = seqs.get(str(g.get("seqid")))
        if sq is None:
            continue
        lo, hi, st = int(g["start"]), int(g["end"]), str(g["strand"])
        pos[rbs_bin(sq, lo, hi, st)] += 1
        for a, b in alt_starts(sq, lo, hi, st):
            neg[rbs_bin(sq, a, b, st)] += 1
    npos, nneg = max(sum(pos.values()), 1), max(sum(neg.values()), 1)
    return {b: math.log(((pos.get(b, 0) + 1) / (npos + 28))
                        / ((neg.get(b, 0) + 1) / (nneg + 28))) for b in range(28)}


def build_length_model(stats: dict, overlap_probs: dict, *, min_gene_len: int,
                       max_gene_len: int = 20000,
                       max_overlap_depth: int = 50, overlap_tail_scale: float = 10.0) -> LengthModel:
    return LengthModel.from_stats(
        stats,
        overlap_probs,
        min_gene_len=min_gene_len,
        max_gene_len=max_gene_len,
        overlap_prior="smooth",
        max_overlap_depth=max_overlap_depth,
        overlap_tail_scale=overlap_tail_scale,
    )


